import{_ as t,o,c as r,a5 as a}from"./chunks/framework.BfQ7H7Qx.js";const h=JSON.parse('{"title":"Neo4j Trend Knowledge Graph Core, Workspace Trend Explorer & Brand-Fit Matching","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/05-ai-rag-and-crawler/neo4j-trend-knowledge-graph/spec.md","filePath":"feature/modules/05-ai-rag-and-crawler/neo4j-trend-knowledge-graph/spec.md"}'),d={name:"feature/modules/05-ai-rag-and-crawler/neo4j-trend-knowledge-graph/spec.md"};function n(c,e,i,s,l,p){return o(),r("div",null,[...e[0]||(e[0]=[a('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Master Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="neo4j-trend-knowledge-graph-core-workspace-trend-explorer-brand-fit-matching" tabindex="-1">Neo4j Trend Knowledge Graph Core, Workspace Trend Explorer &amp; Brand-Fit Matching <a class="header-anchor" href="#neo4j-trend-knowledge-graph-core-workspace-trend-explorer-brand-fit-matching" aria-label="Permalink to &quot;Neo4j Trend Knowledge Graph Core, Workspace Trend Explorer &amp; Brand-Fit Matching&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Module Slug</strong></td><td style="text-align:left;"><code>neo4j-trend-knowledge-graph</code></td></tr><tr><td style="text-align:left;"><strong>Category</strong></td><td style="text-align:left;"><code>05-ai-rag-and-crawler</code> — AI Trend Crawler, Neo4j Knowledge Graph &amp; Brand RAG</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Admin</code></td></tr><tr><td style="text-align:left;"><strong>Consolidated Feature Scopes</strong></td><td style="text-align:left;"><code>trend-graph-core</code>, <code>trend-graph-ui</code>, <code>trend-viewer</code>, <code>workspace-trend-explorer</code>, <code>trend-fit</code></td></tr><tr><td style="text-align:left;"><strong>Aligned SRS Domains</strong></td><td style="text-align:left;"><a href="./../../../srs/06-ai-features/3-7-1-view-trending-topics-suggestions/spec.html">FR 3.7.1 — View Trending Topics</a> · <a href="./../../../srs/06-ai-features/3-7-2-view-ai-trend-knowledge-graph/spec.html">FR 3.7.2 — View AI Trend Knowledge Graph</a></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-architectural-motivation" tabindex="-1">1. Objective &amp; Architectural Motivation <a class="header-anchor" href="#_1-objective-architectural-motivation" aria-label="Permalink to &quot;1. Objective &amp; Architectural Motivation&quot;">​</a></h2><p>Combine the <strong>Neo4j Trend Knowledge Graph</strong> schema &amp; traversal engine (<code>trend-graph-core</code>), interactive Admin &amp; Workspace graph/table explorers (<code>trend-graph-ui</code>, <code>trend-viewer</code>, <code>workspace-trend-explorer</code>), and <strong>Brand-Fit Trend Scoring</strong> (<code>trend-fit</code> — matching live trends + Vietnamese lunar/seasonal moments against a Workspace&#39;s Brand Profile &amp; safety rules to launch 1-click trend-grounded captions).</p><h2 id="_2-user-stories" tabindex="-1">2. User Stories <a class="header-anchor" href="#_2-user-stories" aria-label="Permalink to &quot;2. User Stories&quot;">​</a></h2><ul><li>As an <code>Owner</code>, <code>Manager</code>, or <code>Creator</code>, I want to explore live trends ranked by Brand-Fit (<code>GET /api/v1/workspaces/{workspaceId}/ai/trend-fit</code> and <code>/workspaces/{workspaceId}/trends</code>), inspect historical momentum charts and source posts, and launch &#39;Write Post with Trend&#39; directly into the Editor.</li><li>As an <code>Admin</code>, I want an interactive force-directed Neo4j graph canvas (<code>TrendGraphCanvas.tsx</code>) to inspect <code>Trend</code>, <code>Topic</code>, <code>Hashtag</code>, and <code>Entity</code> co-occurrence clusters.</li></ul><h2 id="_3-consolidated-acceptance-criteria" tabindex="-1">3. Consolidated Acceptance Criteria <a class="header-anchor" href="#_3-consolidated-acceptance-criteria" aria-label="Permalink to &quot;3. Consolidated Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Neo4j Graph Core (<code>trend-graph-core</code>):</strong> <code>trend_graph_mapping.py</code> and <code>trend_graph_service.py</code> maintain idempotent <code>MERGE</code> constraints on <code>Trend</code>, <code>Topic</code>, <code>Keyword</code>, <code>Hashtag</code>, <code>Entity</code>, and <code>PlatformSource</code> nodes with weighted <code>CO_OCCURS_WITH</code> and <code>MENTIONED_IN</code> edges, supporting bounded <code>/overview</code>, <code>/neighborhood</code>, <code>/nodes</code>, and <code>/expand</code> queries.</li><li><strong>Interactive Graph UI &amp; Workspace Trend Explorer (<code>trend-graph-ui</code>, <code>trend-viewer</code>, <code>workspace-trend-explorer</code>):</strong> <code>TrendGraphWorkspace.tsx</code> renders zoomable graph topologies + <code>TrendGraphInspector.tsx</code> side panels; <code>pages/workspace-trends/index.tsx</code> (<code>WorkspaceTrendController</code> <code>/trends</code>, <code>/matrix</code>, <code>/history</code>) renders matrix heatmaps, sparkline history charts (<code>TrendHistoryCharts.tsx</code>), and verified source post drawers (<code>TrendSourcePosts.tsx</code>).</li><li><strong>Brand-Fit Trend Selection (<code>trend-fit</code>):</strong> <code>app/services/trend_fit/</code> (<code>profile.py</code>, <code>lunar.py</code>, <code>moments.py</code>, <code>matching.py</code>, <code>safety.py</code>, <code>graph_context.py</code>) evaluates active trends against Workspace industry, Brand Knowledge RAG profile, Vietnamese lunar/holiday calendar moments, and brand-safety filters (<code>GET /api/v1/workspaces/{workspaceId}/ai/trend-fit</code>), feeding selected trend context directly into FR 3.7.6 (<code>Generate Caption</code>).</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Every user-facing string, tooltip, dialog prompt, status badge, and error banner uses key-parallel translations (<code>trends.{explorer,matrix,history,fit,graph}.*</code> in <code>src/i18n/locales/{vi,en}/trends.json</code>) on <code>brandhub-web</code> and <code>tr()</code> (<code>en.json</code> + <code>vi/common.json</code>) on <code>brandhub-mobile-app</code> with zero hardcoded Vietnamese or English strings in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All surfaces, drawers, badges, charts, and interactive controls use semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useAppPreferences().palette</code> tokens on Mobile, achieving WCAG AA contrast in both Light and Dark themes.</li></ol><h2 id="_4-ui-ux-surfaces-lifecycle-states" tabindex="-1">4. UI / UX Surfaces &amp; Lifecycle States <a class="header-anchor" href="#_4-ui-ux-surfaces-lifecycle-states" aria-label="Permalink to &quot;4. UI / UX Surfaces &amp; Lifecycle States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> <code>pages/workspace-trends/index.tsx</code> (<code>TrendMatrix</code>, <code>TrendTable</code>, <code>TrendHistoryPanel</code>, <code>TrendSourcePosts</code>), <code>pages/admin/components/AdminTrendGraphPanel.tsx</code> (<code>TrendGraphCanvas</code>, <code>TrendGraphScene</code>, <code>TrendGraphInspector</code>)</li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/more/SocialTrendsScreen.tsx</code>, <code>src/services/trendService.ts</code></li><li><strong>UI States:</strong><ul><li><strong>Loading / Streaming:</strong> Deterministic skeleton placeholders, progress bars, and disabled submit buttons preventing duplicate requests.</li><li><strong>Empty / Onboarding:</strong> Contextual empty state with localized call-to-action and zero fabricated mock fallback data.</li><li><strong>Active / Realtime Sync:</strong> Scoped <code>TanStack Query</code> cache updates + WebSocket/SSE/polling synchronization where applicable.</li><li><strong>Error / Conflict Recovery:</strong> Actionable localized error banners (<code>400/403/404/409/429/503</code>) preserving unsaved user input.</li></ul></li></ul><h2 id="_5-api-messaging-protocol-contract" tabindex="-1">5. API, Messaging &amp; Protocol Contract <a class="header-anchor" href="#_5-api-messaging-protocol-contract" aria-label="Permalink to &quot;5. API, Messaging &amp; Protocol Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Route / Channel / Filter</th><th style="text-align:left;">Auth / Scope</th><th style="text-align:left;">Service &amp; Handler</th></tr></thead><tbody><tr><td style="text-align:left;">`GET /api/v1/workspaces/{workspaceId}/trends[/matrix</td><td style="text-align:left;">/history]`</td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>)</td></tr><tr><td style="text-align:left;"><code>GET /api/v1/workspaces/{workspaceId}/ai/trend-fit</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>)</td><td style="text-align:left;"><code>AiCaptionController.trendFit()</code> -&gt; <code>trends.py</code> <code>POST /ai/trends/for-brand</code></td></tr><tr><td style="text-align:left;"><code>GET/POST /api/v1/admin/ai/trend-graph/**</code></td><td style="text-align:left;">Bearer (<code>Admin</code>)</td><td style="text-align:left;"><code>AdminTrendGraphController</code> -&gt; <code>trend_graph.py</code> (<code>/ai/graph/explorer/*</code>)</td></tr></tbody></table><h2 id="_6-error-handling-security-edge-cases" tabindex="-1">6. Error Handling, Security &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-security-edge-cases" aria-label="Permalink to &quot;6. Error Handling, Security &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Workspace Without Brand Docs:</strong> <code>trend-fit</code> gracefully falls back to Workspace industry/description metadata + seasonal moments (<code>lunar.py</code>) without failing.</li><li><strong>Sensitive / Controversial Viral Trend:</strong> <code>trend_fit/safety.py</code> filters political/tragedy/unsafe viral spikes from commercial brand recommendations.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Aligned SRS Functional Requirements:</strong> <a href="./../../../srs/06-ai-features/3-7-1-view-trending-topics-suggestions/spec.html">FR 3.7.1 — View Trending Topics</a> · <a href="./../../../srs/06-ai-features/3-7-2-view-ai-trend-knowledge-graph/spec.html">FR 3.7.2 — View AI Trend Knowledge Graph</a></li><li><strong>BA &amp; Architecture References:</strong> <a href="./../../../../ba/06-ai-features.html">BA 06 AI Features</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Production code verified across backend, AI/publisher workers, Web, and Mobile; <code>vi.json</code> + <code>en.json</code> parity verified; Light/Dark mode audited; all automated verification suites in <a href="./test.html">test.md</a> passing.</li><li><strong>Out of Scope:</strong> De-scoped SRS items (livestream features, subscription plan downgrades, PayOS/VNPay/Stripe gateways, Zalo OA publishing, or copyright/plagiarism scanning).</li></ul>',19)])])}const u=t(d,[["render",n]]);export{h as __pageData,u as default};
